-- Dumping data for table eznidaric.dogadanja: ~8 rows (approximately)
INSERT INTO `dogadanja` (`id`, `obicaj_id`, `naziv`, `opis`, `datum_pocetka`, `datum_zavrsetka`, `lokacija`, `status_objave`, `created_at`, `updated_at`, `naslovna_slika`) VALUES
	(9, 11, 'Potraga za Franom 2027\'', 'Pridružite nam se u tradicionalnoj Potrazi za Franom! Na Čistu srijedu Puntari kreću po mjestu u potragu za Franom koji se sakrio, pa sada više nema koga okriviti za sve loše što se dogodilo tijekom protekle godine.', '2027-02-10 20:00:00', '2027-02-10 23:59:00', 'Punat', 1, '2026-08-31 04:53:56', '2026-08-31 05:27:28', '1788152036030-698352002.png'),
	(10, 10, 'Kordija 2027\'', 'Mladići i divojke, pridružite se Kordiji! Dođite i budite dio jednog od najpoznatijih puntarskih mesopusnih običaja. Sačuvajmo zajedno tradiciju Kordije i prenesimo je na nove generacije.', '2027-02-08 18:00:00', '2027-02-08 22:00:00', 'Punat', 1, '2026-08-31 04:57:53', '2026-08-31 05:27:40', '1788152273418-928972151.png'),
	(11, 9, 'Mesopust 2027\'', 'Pridružite nam se na Mesopustu! Dođite 9. veljače i zajedno s nama obilježite završetak mesopusnog razdoblja u Puntu. Očekuje vas tradicionalno suđenje Mesopustu i završnica jednog od najvažnijih puntarskih običaja. Dođite pod maskom, budite dio puntarske tradicije i zajedno uzviknimo – Živio Pust!', '2027-02-09 12:00:00', '2027-02-09 23:59:00', 'Punat', 1, '2026-08-31 05:27:20', '2026-08-31 05:27:20', '1788154040238-215757129.jpg'),
	(12, 13, 'Prvi četvrtak 27\'', 'Maškare četvrtkom ponovno kreću po Puntu! Maškarajte se i pridružite nam se u tradicionalnom obilasku mjesta. Oživimo zajedno puntarske ulice i sačuvajmo ovaj veseli mesopusni običaj. Vidimo se u četvrtak!', '2027-01-07 18:00:00', '2027-01-07 22:00:00', 'Punat', 1, '2026-08-31 05:33:22', '2026-08-31 05:33:22', '1788154402426-826196256.jpg'),
	(13, 13, 'Drugi četvrtak 27\'', 'Maškare četvrtkom ponovno kreću po Puntu! Maškarajte se i pridružite nam se u tradicionalnom obilasku mjesta. Oživimo zajedno puntarske ulice i sačuvajmo ovaj veseli mesopusni običaj. Vidimo se u četvrtak! 🎭', '2027-01-14 18:00:00', '2027-01-14 22:00:00', 'Punat', 1, '2026-08-31 05:34:30', '2026-08-31 05:34:30', '1788154470587-425654746.jpg'),
	(14, 13, 'Treći četvrtak 27\'', 'Maškare četvrtkom ponovno kreću po Puntu! Maškarajte se i pridružite nam se u tradicionalnom obilasku mjesta. Oživimo zajedno puntarske ulice i sačuvajmo ovaj veseli mesopusni običaj. Vidimo se u četvrtak! 🎭', '2027-01-21 18:00:00', '2027-01-21 22:00:00', 'Punat', 1, '2026-08-31 05:36:53', '2026-08-31 05:36:53', '1788154613449-544585810.jpg'),
	(15, 13, 'Četvrti četvrtak', 'Maškarajte se i pridružite nam se u tradicionalnom obilasku mjesta. Oživimo zajedno puntarske ulice i sačuvajmo ovaj veseli mesopusni običaj. Vidimo se u četvrtak! 🎭', '2027-01-28 18:00:00', '2027-01-28 22:00:00', 'Punat', 1, '2026-08-31 05:38:16', '2026-08-31 05:38:16', '1788154695950-948029013.jpg'),
	(16, 13, 'Četvrtak bez struje 27\'', 'Četvrtak bez struje je večer za maškare, dobru ekipu i još bolju atmosferu! 🎭 Nema benda ni velike organizacije – instrumente uzimamo u svoje ruke, pjevamo, sviramo i zabavljamo se kako najbolje znamo. Maškarajte se, povedite ekipu i pridružite nam se. \r\nŽivio Pust!', '2027-02-04 18:00:00', '2027-02-04 23:59:00', 'Punat', 1, '2026-08-31 05:40:38', '2026-08-31 05:40:38', NULL),
	(17, 12, 'Potezanje komoštri 26\'', 'Vrijeme je za potezanje komoštri! Na Badnjak se u Puntu još jednom okupljamo uz jedan od naših starih običaja. Pridružite nam se u ranojutarnjem potezanju komoštri kroz mjesto i budite dio tradicije koja se i danas čuva. Vidimo se na Badnjak!', '2026-12-24 10:00:00', '2026-12-24 13:00:00', 'Punat', 1, '2026-08-31 05:42:34', '2026-08-31 05:42:34', '1788154954474-894620477.jpg'),
	(18, 8, 'Prvu nedilju od maja 27\'', 'Prva nedilja od maja je pred nami! Pridružite nam se u obilježavanju jednog od posebnih puntarskih običaja i provedite dan uz druženje i tradiciju koja već generacijama okuplja Puntare. Vidimo se prve nedilje od maja!', '2027-05-01 18:00:00', '2027-05-02 12:00:00', 'Punat', 1, '2026-08-31 05:45:19', '2026-08-31 05:45:19', NULL);

