-- Dumping data for table eznidaric.obicaji: ~6 rows (approximately)
INSERT INTO `obicaji` (`id`, `naziv`, `kratki_opis`, `detaljni_opis`, `povijest`, `mjesto`, `organizator`, `naslovna_slika`, `status_objave`, `created_at`, `updated_at`) VALUES
	(8, 'Prva nedilja od maja', 'Prva nedilja od maja tradicionalni je puntarski običaj kojim se obilježavao ulazak mladića u odraslu dob i njihov skori odlazak u vojsku. Središnji simbol običaja je „maj“ – trešnjino stablo ukrašeno rupcima, oko kojega su se okupljali mladi, plesali i veselili uz glazbu.', 'Prva nedilja od maja jedan je od prepoznatljivih običaja mjesta Punat koji okuplja mlade i simbolizira pripadnost generaciji, zajedništvo i odrastanje. Središnji dio običaja je postavljanje „maja“ – trešnjina stabla koje mladići donose u mjesto i postavljaju na placu.\r\n\r\nTrešnja se ukrašava rupcima koje donose djevojke, nakon čega postaje središte okupljanja i veselja. Uz maj se vežu pjesma, glazba i ples, a posebno mjesto u tradiciji imaju sopile i puntarski tanac. Okupljanje oko maja bilo je prilika za druženje mladih, ples i iskazivanje simpatija.\r\n\r\nVažan dio običaja je i čuvanje postavljenog maja. Njegovo rušenje ili odnošenje smatralo se sramotom za generaciju koja ga je postavila, zbog čega su mladići uz njega ostajali i tijekom noći. Upravo su nadmetanja među generacijama i susjednim mjestima postala dijelom priča koje se prenose uz ovu tradiciju.\r\n\r\nDanas maj postavlja generacija mladih koja tijekom godine navršava osamnaest godina. Iako se način obilježavanja tijekom vremena promijenio, običaj i dalje povezuje mlade s tradicijom mjesta te pridonosi očuvanju kulturnog identiteta Punta.', 'U izvornom obliku običaj Prve nedilje od maja bio je povezan s generacijom mladića koja se pripremala za odlazak u vojsku. Mladići su nabavljali trešnjino stablo, najčešće na području Muraja ili Lakmartina u okolici Kornića, te ga postavljali na sredinu place. Od stabla prema okolnim kućama protezali su se konopci na koje su se vješali rupci koje su donosile djevojke.\r\n\r\nNakon postavljanja i ukrašavanja maja slijedilo je zajedničko druženje uz glazbu i ples. Posebnu važnost imalo je čuvanje trešnje jer bi njezino rušenje iz prkosa predstavljalo sramotu za mladiće koji su je postavili.\r\n\r\nPrestankom nekadašnje obveze odlaska u vojsku običaj je izgubio svoju prvotnu funkciju, ali nije nestao. Prilagodio se novim društvenim okolnostima pa je ulogu nekadašnjih vojnih obveznika preuzela generacija koja navršava osamnaest godina. Na taj je način sačuvana osnovna povezanost običaja s prijelazom mladih prema odrasloj dobi.', 'Punat', 'Mještani Punta', '1788087233657-207665413.jpg', 1, '2026-08-30 10:51:44', '2026-08-30 10:57:12'),
	(9, 'Mesopust', 'Mesopust je jedan od najznačajnijih i najživljih tradicijskih običaja Punta. Pokladno razdoblje ispunjeno je pjesmom, plesom, maskama i zajedničkim okupljanjima, a završava pokladnim utorkom i simboličnim oproštajem od mesopusta Frana.', 'Mesopust zauzima posebno mjesto u tradicijskom životu Punta. Riječ je o pokladnom razdoblju tijekom kojega se kroz niz običaja, okupljanja, pjesmu, ples i humor uključuje velik dio lokalne zajednice. Mesopusna događanja tradicionalno započinju nakon blagdana Sveta tri kralja i traju sve do Pepelnice.\r\n\r\nTijekom mesopusnog razdoblja važnu ulogu imaju glazba i ples. Subotnja okupljanja bila su povezana s mesopusnim tancem, dok su djeca i mladi četvrtkom obilazili puntarske kuće pjevajući pokladne pjesme. Za pjesmu su ih domaćini darivali jajima, slasticama i drugim darovima. Time mesopust nije bio samo pojedinačna proslava, već razdoblje koje je tijekom više tjedana unosilo posebno ozračje u svakodnevni život mjesta.\r\n\r\nVrhunac običaja dolazi tijekom posljednjih dana mesopusta. Nedjelja je obilježena maskama i zabavom, nakon čega u ponedjeljak slijedi tradicionalna Kordija. Pokladni utorak donosi mesopusnu povorku kroz Punat, u kojoj sudjeluju mesopustari i ostali sudionici.\r\n\r\nPosebno mjesto u običaju pripada mesopusnom lutku Franu. Mesopustari su tradicionalno zaduženi za njegovu izradu, kao i za organizaciju završnih događanja. Važan dio pokladnog utorka je i napovid, tekst u kojem se na šaljiv i ironičan način osvrće na događaje koji su obilježili život Punta tijekom protekle godine.\r\n\r\nMesopust tako povezuje različite elemente puntarske nematerijalne baštine – lokalni govor, humor, pjesmu, sopile, tanac, maske i zajedničko sudjelovanje mještana. Njegova vrijednost nije samo u zabavi, već i u okupljanju zajednice te prenošenju običaja s jedne generacije na drugu.', 'Puntarski mesopusni običaji pripadaju tradiciji koja je duboko ukorijenjena u život lokalne zajednice. Pokladno razdoblje može se promatrati kroz nekoliko etapa: vrijeme od Sveta tri kralja do završnog pokladnog tjedna, završne dane mesopusta te Pepelnicu, kojom započinje korizmeno razdoblje.\r\n\r\nPosebno važan bio je pokladni utorak. Mesopustari su se brinuli o izradi lutka Frana, zajedničkoj maski, organizaciji povorke i sastavljanju napovidi. Povorka je prolazila kroz Punat, nakon čega bi se sudionici okupili na placi gdje se čitala napovid. U njoj su se događaji iz protekle godine prikazivali na šaljiv i ironičan način.\r\n\r\nZavršetak mesopusta označavao je prijelaz iz razdoblja veselja u vrijeme Korizme. Nakon završne zabave i ponoći mesopusno slavlje prestajalo je, a uz Frana se vezivao još jedan običaj – njegovo skrivanje i potraga koja je simbolički pratila završetak pokladnog razdoblja.\r\n\r\nIako su se pojedini načini obilježavanja tijekom vremena mijenjali, mesopust je ostao važan dio puntarske tradicije. Upravo njegovo trajanje kroz više tjedana i povezanost brojnih manjih običaja pokazuju koliko je nekada bio, ali i koliko je ostao, važan za društveni i kulturni život Punta.', 'Punat', 'Mještani Punta', '1788094392862-929546257.jpg', 1, '2026-08-30 12:52:51', '2026-08-30 12:53:12'),
	(10, 'Kordija', 'Kordija je osebujan puntarski mesopusni običaj koji se tradicionalno održava u ponedjeljak prije završetka mesopusta. Mladići i djevojke okupljaju se u parove, obilaze njihove domove te uz pjesmu, druženje i puntarski tanac čuvaju jednu od prepoznatljivih tradicija Punta.', 'Kordija je jedan od najprepoznatljivijih običaja puntarskog mesopusnog razdoblja. Održava se u ponedjeljak završnog tjedna mesopusta, neposredno prije pokladnog utorka. Za razliku od uobičajenih pokladnih povorki obilježenih maskama, sudionici Kordije tradicionalno nisu maskirani, već se ističu posebnim elementima odjeće.\r\n\r\nU Kordiji sudjeluju mladići i djevojke koji se prethodno dogovaraju s kim će biti u paru. Mladići se okupljaju u Narodnom domu, nakon čega kreću u obilazak kuća djevojaka. Dolaskom u svaku novu kuću pridružuje se novi par pa povorka postupno postaje sve brojnija.\r\n\r\nObilazak je popraćen pjesmom, veseljem i druženjem. Domaćini dočekuju sudionike, a nakon kraćeg zadržavanja povorka nastavlja prema sljedećoj kući. Na taj način Kordija povezuje pojedine obitelji i cijelo mjesto u zajedničko mesopusno slavlje.\r\n\r\nSudionici su se tradicionalno mogli prepoznati i prema karakterističnim detaljima odjeće. Mladići su nosili crvene marame oko vrata, dok su djevojke na glavama imale takozvane „francuske“ kape. Ti detalji dodatno su izdvajali članove Kordije od ostalih sudionika mesopusnih događanja.\r\n\r\nNakon što se okupe svi parovi, slijedi jedan od najvažnijih dijelova običaja – odlazak na placu i zajedničko izvođenje puntarskog tanca. Kordija tako objedinjuje druženje mladih, glazbu i ples te predstavlja važan dio puntarskog kulturnog identiteta.', 'Kordija je tradicionalno bila snažno povezana s društvenim životom mladih u Puntu. Sudjelovanje nije predstavljalo samo dio mesopusnog veselja, već i priliku za druženje mladića i djevojaka te njihovo uključivanje u zajednički život mjesta.\r\n\r\nPrema zapisima o običaju, mladići i djevojke međusobno su se dogovarali o parovima i organizaciji Kordije. Nakon okupljanja mladića započinjao je obilazak kuća djevojaka, pri čemu bi se svaki novi par pridružio skupini. Nakon obilaska okupljeni parovi odlazili su na placu gdje su plesali tradicionalni puntarski tanac.\r\n\r\nNekada je sudjelovanje u Kordiji bilo povezano i sa životnim razdobljem mladih. Parovi su u Kordiju tradicionalno odlazili sve do ženidbe, dok se u novije vrijeme sudjelovanje može završiti ranije zbog promijenjenog načina života i drugih obveza. S vremenom su se mijenjali i pojedini dijelovi završetka običaja, pa se kao noviji oblik spominje zajednička večera sudionika u Narodnom domu.\r\n\r\nUnatoč promjenama, osnovna obilježja Kordije – okupljanje parova, obilazak kuća, pjesma, druženje i puntarski tanac – omogućila su da običaj ostane prepoznatljiv dio puntarskog mesopusta i primjer prijenosa lokalne tradicije između generacija.', 'Punat', 'Mještani Punta', '1788095969563-217432796.png', 1, '2026-08-30 13:18:45', '2026-08-30 13:19:29'),
	(11, 'Kabani', 'Kabani su jedinstven puntarski običaj kojim se na Pepelnicu obilježava završetak mesopusnog razdoblja. Odjeveni u tradicionalne vunene kabanice i noseći feraliće, sudionici prolaze ulicama Punta tražeći i dozivajući nestalog mesopusta Frana.', 'Kabani su jedan od osebujnih običaja Punta povezanih sa završetkom mesopusnog razdoblja. Održavaju se na Čistu sredu, odnosno Pepelnicu, kada nakon višednevnog veselja, pjesme, plesa i pokladnih događanja započinje Korizma.\r\n\r\nSredišnji motiv običaja je potraga za mesopustom Franom, slamnatim likom koji je tijekom mesopusta simbolično povezan sa svim nedaćama i događajima protekle godine. Nakon završetka mesopusta Frane nestaje, a Kabani kreću ulicama Punta u potragu za njim.\r\n\r\nSudionici su prepoznatljivi po posebnim kabanicama od grubo češljane vune, prema kojima je običaj i dobio naziv. U rukama nose tradicionalna svjetla – feraliće – kojima osvjetljavaju put dok prolaze puntarskim kalama i voltama. Za razliku od veselih događanja prethodnih mesopusnih dana, potraga za Franom ima drugačije ozračje. Kabani ga dozivaju i oplakuju, a cijeli ophod simbolično označava kraj vremena mesopusnog veselja.\r\n\r\nPotraga je, prema tradiciji, uzaludna. Frane se ne pronalazi, čime se potvrđuje da je mesopust završio i da započinje Korizma. Upravo spoj simbolike, karakteristične odjeće, lokalnog govora i noćnog obilaska mjesta čini Kabane posebno prepoznatljivim dijelom puntarske tradicije.\r\n\r\nObičaj se prenosi među generacijama, a u njemu sudjeluju i mlađi stanovnici Punta. Time Kabani nisu samo prikaz nekadašnjeg načina obilježavanja završetka mesopusta, već tradicija koja nastavlja živjeti unutar lokalne zajednice.', 'Kabani su povezani s posljednjom fazom tradicionalnog puntarskog mesopusta. Nakon pokladnog utorka, povorke, čitanja napovidi i završnog veselja dolazi Pepelnica, kojom završava pokladno i započinje korizmeno razdoblje.\r\n\r\nUz završetak mesopusta vezan je lik Frana. Mesopustari ga skrivaju, nakon čega slijedi njegovo traženje i oplakivanje. Potraga za Franom tako simbolički predstavlja oproštaj od mesopusta i povratak svakodnevnom životu nakon razdoblja pokladne slobode i veselja.\r\n\r\nPrepoznatljivo obilježje Kabana postale su kabanice izrađene od grubo češljane vune i feralići koje sudionici nose prilikom obilaska mjesta. Tradicija nalaže da se Frana ne pronađe, pa njegov nestanak označava konačan završetak mesopusnog razdoblja.\r\n\r\nOčuvanjem ovog običaja održava se povezanost današnjih generacija s puntarskim mesopusnim nasljeđem. Sudjelovanje različitih generacija pokazuje da Kabani nisu ostali samo zabilježeni u pričama i zapisima, nego se običaj nastavlja prenositi i izvoditi.', 'Punat', 'Mještani Punta', '1788096082667-596925042.png', 1, '2026-08-30 13:21:08', '2026-08-30 13:21:22'),
	(12, 'Potezanje komoštri', 'Potezanje komoštri stari je puntarski običaj koji se održava na Badnjak. Djeca i mladi vuku željezne lance nekada korištene na ognjištu, čime se oni čiste, a prema tradiciji buka koju stvaraju tjera zle sile.', 'Potezanje komoštri tradicionalni je puntarski običaj vezan uz Badnjak i nekadašnji način života u Puntu. Komoštre su željezni lanci koji su se koristili na kućnom ognjištu za vješanje posude iznad vatre.\r\n\r\nU običaju su posebno sudjelovala djeca koja su komoštre vukla za sobom po kamenim ulicama Punta. Povlačenjem po tlu lanci su se čistili i postajali sve sjajniji, a među djecom se razvijalo veselo nadmetanje čije će komoštre biti bolje očišćene. Ponekad bi lanac zapeo za kamen pa bi dijete koje ga je vuklo palo, no i takve su situacije bile dio veselja i zajedničkog druženja.\r\n\r\nUz praktično čišćenje komoštri, običaju se pripisuje i simboličko značenje. Prema lokalnoj predaji, buka koja nastaje njihovim povlačenjem trebala je otjerati vještice i druge zle sile te ih držati podalje od mjesta.\r\n\r\nDanas tradicionalna ognjišta više nemaju nekadašnju ulogu u svakodnevnom životu, ali se običaj potezanja komoštri i dalje čuva kao dio puntarske baštine. Njegovim održavanjem mlađe generacije upoznaju nekadašnji način života svojih predaka, dok starije podsjeća na djetinjstvo, mladost i nekadašnji Punat.', 'Potezanje komoštri potječe iz vremena kada je ognjište bilo sastavni dio puntarskih kućanstava. Iznad vatre nalazio se željezni lanac – komoštar – na koji se vješala posuda za pripremu hrane. Zbog svakodnevnog korištenja lanac bi se s vremenom zaprljao i prekrio čađom.\r\n\r\nNa Badnjak su djeca komoštre vukla po kamenim ulicama Punta. Na taj su se način lanci čistili, a djeca su se međusobno natjecala čije će komoštre biti sjajnije i čišće.\r\n\r\nRazvojem suvremenog načina života tradicionalna ognjišta postupno su zamijenjena novijim načinima kuhanja i grijanja, čime su komoštre izgubile svoju nekadašnju praktičnu funkciju. Ipak, običaj je sačuvan kao podsjetnik na prošla vremena i život nekadašnjih generacija Puntara.\r\n\r\nDanas potezanje komoštri ima prvenstveno kulturnu i društvenu vrijednost. Okupljanjem stanovnika i uključivanjem djece običaj prenosi znanje o lokalnoj baštini novim generacijama, a istodobno čuva sjećanje na nekadašnji način života i vjerovanja stanovnika Punta.', 'Punat', 'Mještani Punta', '1788096318643-106644782.jpg', 1, '2026-08-30 13:25:01', '2026-08-30 13:25:18'),
	(13, 'Maškare četvrtkom', 'Maškare četvrtkom dio su puntarske mesopusne tradicije. Od razdoblja nakon Tri kralja pa sve do završetka mesopusta, maškare četvrtkom obilaze kuće mještana Punta, pjevaju pokladne pjesme i druže se s domaćinima, koji ih tradicionalno daruju jajima, kolačima, vinom i drugim darovima.', 'Maškare četvrtkom jedan su od običaja koji obilježavaju mesopusno razdoblje u Puntu. Običaj započinje nakon blagdana Sveta tri kralja i ponavlja se četvrtkom sve do završnih dana mesopusta.\r\n\r\nMaškare obilaze mjesto, dolaze pred kuće mještana te pjesmom najavljuju svoj dolazak. Domaćini ih dočekuju i daruju onime što imaju, tradicionalno jajima, kolačima, vinom i drugim jelom i pićem. Osim samog darivanja, važan dio običaja predstavljaju druženje, pjesma i zajedničko veselje.\r\n\r\nObilasci četvrtkom stvaraju posebno mesopusno ozračje u mjestu jer se pokladna tradicija ne svodi samo na posljednjih nekoliko dana prije Korizme. Ona traje tijekom čitavog mesopusnog razdoblja i iz tjedna u tjedan uključuje mještane u zajedničko slavlje.\r\n\r\nObičaj se nastavlja i u suvremenom životu Punta, a upravo je tradicija okupljanja četvrtkom poslužila kao temelj za nastanak novijeg događanja „Četvrtak bez struje“. Na tom se događanju okupljaju maškarane skupine s otoka Krka i iz okolice, a umjesto angažiranog glazbenog sastava sudionici donose vlastite instrumente te zajedno sviraju i pjevaju. Na taj način novi oblik druženja nastavlja duh tradicionalnih puntarskih mesopusnih četvrtaka.', 'Obilasci kuća četvrtkom dio su dugogodišnje puntarske mesopusne tradicije. Prema zapisima o pokladnim običajima Punta, već prvi četvrtak nakon Tri kralja djeca i mladi odlaze po puntarskim kućama i pjevaju pokladne pjesme. Domaćini ih zauzvrat daruju jajima, slasticama i drugim darovima, a obilasci se nastavljaju četvrtkom tijekom mesopusnog razdoblja.\r\n\r\nIako se način obilježavanja s vremenom mijenjao, osnovna ideja ostala je ista – obilazak mjesta, pjesma, druženje i uključivanje mještana u mesopusno veselje. Tradicija četvrtaka tako povezuje privatni prostor puntarskih domova sa zajedničkim životom mjesta.\r\n\r\nIz ove tradicije razvio se i „Četvrtak bez struje“, suvremeno mesopusno događanje koje zadržava naglasak na zajedničkoj pjesmi, sviranju i druženju. Njegov nastanak pokazuje kako se nematerijalna kulturna baština može prilagođavati novim generacijama, a pritom zadržati povezanost sa starijim običajima.', 'Punat', 'Mještani Punta', '1788097125240-412547362.jpg', 1, '2026-08-30 13:37:54', '2026-08-30 13:38:45');

